 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(Color.rgb(5,5,5));getWindow().setNavigationBarColor(Color.rgb(5,5,5));web=new WebView(this);web.setBackgroundColor(Color.rgb(5,5,5));androidx.core.view.WindowCompat.setDecorFitsSystemWindows(getWindow(),false);safeRoot=new FrameLayout(this);safeRoot.addView(web,new FrameLayout.LayoutParams(-1,-1));mainAd=new AdView(this,"main",value->send("platformAd",App.j("available",value)));safeRoot.addView(mainAd,new FrameLayout.LayoutParams(1,1));setContentView(safeRoot);androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(safeRoot,(v,insets)->{androidx.core.graphics.Insets safe=insets.getInsets(androidx.core.view.WindowInsetsCompat.Type.systemBars()|androidx.core.view.WindowInsetsCompat.Type.displayCutout()|androidx.core.view.WindowInsetsCompat.Type.ime());int gap=Math.round(12*getResources().getDisplayMetrics().density);v.setPadding(safe.left,safe.top+gap,safe.right,safe.bottom);return androidx.core.view.WindowInsetsCompat.CONSUMED;});androidx.core.view.ViewCompat.requestApplyInsets(safeRoot);applyPalette();WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setMediaPlaybackRequiresUserGesture(true);WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){WebResourceResponse res=loader.shouldInterceptRequest(r.getUrl());return res!=null?res:new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return true;}@Override public void onPageFinished(WebView w,String u){loaded=true;send("platformAd",App.j("available",mainAd.ready));}});web.addJavascriptInterface(new Bridge(),"Native");web.loadUrl("https://appassets.androidplatform.net/assets/index.html");ContextCompat.registerReceiver(this,changes,new IntentFilter("com.configmonitor.UPDATE"),ContextCompat.RECEIVER_NOT_EXPORTED);}
