 void positionAd(JSONObject p){if(mainAd==null)return;if(!p.optBoolean("visible")||!mainAd.ready){mainAd.setVisibility(View.GONE);return;}float scale=web.getWidth()/(float)Math.max(1,p.optDouble("viewport",1));int width=Math.max(1,Math.round((float)p.optDouble("width")*scale)),height=Math.max(1,Math.round((float)p.optDouble("height")*scale));FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(width,height);lp.gravity=Gravity.LEFT|Gravity.TOP;lp.leftMargin=Math.round((float)p.optDouble("left")*scale);lp.topMargin=Math.round((float)p.optDouble("top")*scale);mainAd.setLayoutParams(lp);int clipTop=Math.max(0,Math.round((float)(p.optDouble("clipTop")-p.optDouble("top"))*scale));int clipBottom=Math.min(height,Math.round((float)(p.optDouble("clipBottom")-p.optDouble("top"))*scale));mainAd.setClipBounds(new Rect(0,clipTop,width,Math.max(clipTop,clipBottom)));mainAd.setVisibility(clipBottom>clipTop?View.VISIBLE:View.GONE);}
 void applyPalette(){if(safeRoot==null)return;boolean light=App.prefs.getString("theme","dark").equals("light");int color=light?Color.rgb(244,247,246):Color.rgb(5,5,5);safeRoot.setBackgroundColor(color);web.setBackgroundColor(color);getWindow().setStatusBarColor(color);getWindow().setNavigationBarColor(color);androidx.core.view.WindowInsetsControllerCompat bars=androidx.core.view.WindowCompat.getInsetsController(getWindow(),safeRoot);bars.setAppearanceLightStatusBars(light);bars.setAppearanceLightNavigationBars(light);}
